import React from "react";
import InteractiveMap from "./InteractiveMap";

export default function App() {
  return (
    <main className="min-h-screen bg-gray-100">
      {/* Header with logo and title */}
      <header className="bg-[#84000a] text-white py-3 shadow-md">
        <div className="max-w-screen-sm mx-auto flex items-center justify-start px-4 space-x-4">
          {/* Logo on the left */}
          <img
            src={`${process.env.PUBLIC_URL}/stoney_creek_logo_white.png`}
            alt="Stoney Creek Stallions"
            className="h-10 w-auto"
          />

          {/* Title next to logo */}
          <h1 className="text-xl font-bold tracking-wide">
            Stoney Creek Spring Fair
          </h1>
        </div>
      </header>

      {/* Map Section */}
      <section className="p-4">
        <InteractiveMap />
      </section>
    </main>
  );
}
